const MGEO = {
  AL:"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_",
  ready:false, sc:1,
  pathRaw(){
    if(this._raw) return this._raw;
    const p = this.dec(MONACO_DATA.path), out = [];
    for(let i = 0; i < p.length; i += 2) out.push([p[i] / 10, p[i + 1] / 10]);
    return (this._raw = out);
  },
  dec(str){
    const out = [], A = this._lut || (this._lut = (() => { const m = {}; for(let i = 0; i < 64; i++) m[this.AL[i]] = i; return m; })());
    let v = 0, sh = 0;
    for(let i = 0; i < str.length; i++){
      const b = A[str[i]];
      v += (b & 31) * Math.pow(2, sh);
      if(b & 32){ sh += 5; continue; }
      out.push(v % 2 ? -(v + 1) / 2 : v / 2);
      v = 0; sh = 0;
    }
    return out;
  },
  // rings stored as [count, dx, dy, ...] with running deltas
  rings(str, q){
    const a = this.dec(str), out = [];
    let i = 0, px = 0, py = 0;
    while(i < a.length){
      const n = a[i++], r = [];
      for(let k = 0; k < n; k++){ px += a[i++]; py += a[i++]; r.push([px / q * this.sc, py / q * this.sc]); }
      out.push(r);
    }
    return out;
  },
  init(sc){
    if(this.ready && this.sc === sc) return this;
    const D = MONACO_DATA; this.sc = sc;
    const q = D.q;
    // the lap
    const p = this.dec(D.path); this.path = [];
    for(let i = 0; i < p.length; i += 2) this.path.push([p[i] / 10, p[i + 1] / 10]);
    // buildings
    const b = this.dec(D.bld); this.blds = [];
    const LMIDS = ["", "casino", "hotelparis", "cafeparis", "hermitage", "fairmont", "rascasse", "yachtclub",
                   "odeon", "chapel", "palace", "cathedral", "musee"];
    let i = 0, px = 0, py = 0;
    while(i < b.length){
      const n = b[i++], lv = b[i++], kind = b[i++], lm = LMIDS[b[i++]] || "";
      const pts = [];
      for(let k = 0; k < n; k++){ px += b[i++]; py += b[i++]; pts.push([px / q * sc, py / q * sc]); }
      this.blds.push({ pts, lv, kind, lm });
    }
    // the land mask
    const M = D.mask; this.mask = M;
    const [hd, body] = M.rle.split(".");
    const counts = this.dec(hd), runs = this.dec(body);
    const grid = new Uint8Array(M.w * M.h);
    let r = 0;
    for(let row = 0; row < M.h; row++){
      let x = 0;
      for(let k = 0; k < counts[row]; k += 2){
        x += runs[r + k];
        const len = runs[r + k + 1];
        grid.fill(1, row * M.w + x, row * M.w + Math.min(M.w, x + len));
        x += len;
      }
      r += counts[row];
    }
    this.landGrid = grid;
    // terrain grids
    this.ter = {};
    for(const k of ["fine", "coarse"]){
      const g = D.terrain[k];
      this.ter[k] = { N:g.N, M:g.M, x0:g.x0, y0:g.y0, x1:g.x1, y1:g.y1, h:Float32Array.from(this.dec(g.h)) };
    }
    // a light blur on the fine grid: at 40 m spacing the radar still picks up
    // the bigger buildings, and those are not the ground
    { const g = this.ter.fine, N = g.N, Mm = g.M, h = g.h, o = new Float32Array(h);
      for(let pass = 0; pass < 2; pass++){
        for(let rr = 1; rr < N - 1; rr++) for(let c = 1; c < Mm - 1; c++){
          const k = rr * Mm + c;
          o[k] = (h[k] * 4 + h[k - 1] + h[k + 1] + h[k - Mm] + h[k + Mm]) / 8;
        }
        h.set(o);
      } }
    this.poly = {}; for(const k in D.poly) this.poly[k] = this.rings(D.poly[k], q);
    this.line = {}; for(const k in D.line) this.line[k] = this.rings(D.line[k], q);
    this.streets = D.streets.map(s => s ? this.rings(s, q) : []);
    const pts = str => { const a = this.dec(str), out = []; let x = 0, y = 0;
      for(let k = 0; k < a.length; k += 2){ x += a[k]; y += a[k + 1]; out.push([x * sc, y * sc]); } return out; };
    this.trees = pts(D.trees); this.lamps = pts(D.lamps);
    this.lm = {}; for(const k in D.lm) this.lm[k] = [D.lm[k][0] * sc, D.lm[k][1] * sc];
    this.ready = true;
    return this;
  },
  // is there land under this point? (sea beyond the mask's edge)
  land(x, y){
    const M = this.mask, s = this.sc;
    const c = Math.floor((x / s - M.x0) / M.ms), r = Math.floor((y / s - M.y0) / M.ms);
    if(c < 0 || r < 0 || c >= M.w || r >= M.h) return y / s < M.y0 + 200;      // north of the box is France
    return this.landGrid[r * M.w + c] === 1;
  },
  _grid(g, x, y){
    const fx = (x - g.x0) / (g.x1 - g.x0) * (g.M - 1), fy = (y - g.y0) / (g.y1 - g.y0) * (g.N - 1);
    if(fx < 0 || fy < 0 || fx > g.M - 1 || fy > g.N - 1) return null;
    const c = Math.min(g.M - 2, Math.floor(fx)), r = Math.min(g.N - 2, Math.floor(fy));
    const a = fx - c, b = fy - r, H = g.h, M = g.M;
    return H[r * M + c] * (1 - a) * (1 - b) + H[r * M + c + 1] * a * (1 - b) +
           H[(r + 1) * M + c] * (1 - a) * b + H[(r + 1) * M + c + 1] * a * b;
  },
  // ground height above sea level, before the circuit is cut into it
  dem(x, y){
    const s = this.sc; x /= s; y /= s;
    const f = this._grid(this.ter.fine, x, y);
    if(f != null) return f;
    const c = this._grid(this.ter.coarse, x, y);
    return c == null ? 0 : c;
  },
};

/* the circuit's own elevation, as a smooth monotone curve through the points:
   unlike elevPW this keeps the gradient continuous, so a long climb is a climb
   and not a staircase of flat landings */
function elevMC(pts){
  const n = pts.length, U = pts.map(p => p[0]), Z = pts.map(p => p[1]);
  const d = [], m = new Array(n).fill(0);
  for(let i = 0; i < n - 1; i++) d.push((Z[i + 1] - Z[i]) / (U[i + 1] - U[i]));
  for(let i = 1; i < n - 1; i++) m[i] = d[i - 1] * d[i] <= 0 ? 0 : (d[i - 1] + d[i]) / 2;
  m[0] = d[0]; m[n - 1] = d[n - 2];
  for(let i = 0; i < n - 1; i++){                  // Fritsch-Carlson: no overshoot
    if(d[i] === 0){ m[i] = m[i + 1] = 0; continue; }
    const a = m[i] / d[i], b = m[i + 1] / d[i], s = a * a + b * b;
    if(s > 9){ const t = 3 / Math.sqrt(s); m[i] = t * a * d[i]; m[i + 1] = t * b * d[i]; }
  }
  return u => {
    u = ((u % 1) + 1) % 1;
    let i = 0; while(i < n - 2 && u > U[i + 1]) i++;
    const h = U[i + 1] - U[i], t = (u - U[i]) / h, t2 = t * t, t3 = t2 * t;
    return (2 * t3 - 3 * t2 + 1) * Z[i] + (t3 - 2 * t2 + t) * h * m[i] + (-2 * t3 + 3 * t2) * Z[i + 1] + (t3 - t2) * h * m[i + 1];
  };
}


export { MGEO, elevMC };
